	private static boolean hasStableBindings(BindingSetAssignment assignment) {
		Iterable<BindingSet> bindingSets = assignment.getBindingSets();
		if (bindingSets instanceof BindingSetAssignment.RepeatableBindingSetSource) {
			return true;
		}
		if (!(bindingSets instanceof List<?> rows)) {
			return false;
		}
		for (Object row : rows) {
			if (!isStableBindingSet(row)) {
				return false;
			}
		}
		return true;
	}

	private static boolean isStableBindingSet(Object row) {
		return row == EmptyBindingSet.getInstance()
				|| row instanceof BindingSet bindingSet && bindingSet.getClass() == ListBindingSet.class;
	}
